import csv

def extract(path):
    with open(path, newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))

def normalise(r):
    return {
        'customer_id': int(r['customer_id']),
        'name': (r['name'] or '').strip().title(),
        'email': (r['email'] or '').strip().lower(),
        'country': (r['country'] or '').strip().upper(),
        'signup_date': r['signup_date'].strip(),
        'updated_at': r['updated_at'].strip(),
    }

def dedupe_latest(rows):
    best = {}
    for r in rows:
        k = r['customer_id']
        if k not in best or r['updated_at'] > best[k]['updated_at']:
            best[k] = r
    return list(best.values())

